using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _pricing = new();

    private int Charged(LoyaltyTier tier, int subtotalCents) =>
        _pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier)).TotalCents;

    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeCustomerIsCharged9500CentsOnA10000CentSubtotal() =>
        Assert.Equal(9500, Charged(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverCustomerIsCharged9000CentsOnA10000CentSubtotal() =>
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldCustomerIsCharged8500CentsOnA10000CentSubtotal() =>
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));

    // Bronze customer's reduction lands on a whole cent in their favour
    [Fact]
    public void S4_BronzeCustomerIsCharged7CentsOnA7CentSubtotal() =>
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
}

